% Question 5
close all;
clc;

addpath('PhysioToolkitCardiacOutput_MatlabCode/2analyze');
addpath('PhysioToolkitCardiacOutput_MatlabCode/3estimate')

Fs = 125;

patients = {'s00020', 's00138', 's00214'};

for i = 1:length(patients) %[output:group:1517063e]
    % Get patient folder
    patientFolder = patients{i};

    abpFiles = dir(fullfile(patientFolder, '*_ABP.txt'));
    tcoFiles = dir(fullfile(patientFolder, '*n.txt'));

    % Load data
    ABP_timeseries = readmatrix(fullfile(patientFolder, abpFiles(1).name));
    TCO_data = readmatrix(fullfile(patientFolder, tcoFiles(1).name));

    % Print which patient it is
    fprintf('\nProcessing Patient %s\n', patients{i}); %[output:5de9dcd1] %[output:2fe1ad36] %[output:878e72fb]

    % 1st 12 hours
    startTime = 60; % min
    endTime = 100; % min

    t_start_ABP = ABP_timeseries(1, 1);
    t_start_TCO = TCO_data(1, 1);

    ABP_window = ABP_timeseries(:, 1) < t_start_ABP + startTime*60*60;
    TCO_window = TCO_data(:, 1) < t_start_TCO + 12*60*60;

    ABP_12h = ABP_timeseries(ABP_window, :);
    TCO_12h = TCO_data(TCO_window, :);

    ABP = ABP_12h(:, 2);

    % Extract ABP features
    onset = wabp(ABP);
    feat = abpfeature(ABP, onset);
    beatq = jSQI(feat, onset, ABP);

    % Parlikar estimation
    [X, t, tau] = parlikarCO(ABP, onset, feat, beatq, Fs, 9);
    %t = ABP_12h(1, 1)/60 + (onset(1:length(X)) - 1)/(Fs*60);

    % Thermodilution measurements
    TCO = TCO_12h(:, 16);
    validTCO = TCO > 0 & isfinite(TCO);

    TCO_valid = TCO(validTCO);
    time_TCO = TCO_12h(validTCO, 1)/60;

    % Calibrate using 1st valid TCO measurement
    %firstIndex = find(validTCO, 1, 'first');
    firstIndex = 1;

    referenceCO = TCO_valid(firstIndex);
    referenceTime = time_TCO(firstIndex);

    calWindow = t > referenceTime - 1 & t <= referenceTime & isfinite(X) & X > 0;
    calValue = median(X(calWindow), 'omitnan');

    if isempty(calValue) || ~isfinite(calValue) || calValue <= 0
        error('No valid estimate in calibration window!');
    end

    calibrationFactor = referenceCO/calValue;
    CO_parlikar = calibrationFactor*X;

    % Compare with thermodilution
    % Match each TCO measurement to nearest Parlikar estimate
    validCO = isfinite(t) & isfinite(CO_parlikar);

    t_valid = t(validCO);
    CO_valid = CO_parlikar(validCO);

    [t_valid, uniqueIndex] = unique(t_valid);
    CO_valid = CO_valid(uniqueIndex);

    CO_matched = interp1(t_valid, CO_valid, time_TCO, 'nearest', NaN);
    % Excluded calibration measurement from performance evaluation
    evaluation = isfinite(CO_matched);
    evaluation(1) = false;

    reference = TCO_valid(evaluation);
    estimate = CO_matched(evaluation);

    errorValues = estimate - reference;
    bias = mean(errorValues);
    RMSE = sqrt(mean(errorValues.^2));
    MAE = mean(abs(errorValues));
    percentageError = 100*std(errorValues)/mean(reference);
    RMSNE = 100 * RMSE / mean(reference);

    fprintf('\nParlikar performance - %s\n', patients{i}); %[output:951f2af8] %[output:98437e31] %[output:6db91301]
    fprintf('Bias: %.3f\n', bias); %[output:1386d489] %[output:9269b4cc] %[output:694e24f3]
    fprintf('RMSE: %.3f\n', RMSE); %[output:3b1f07ec] %[output:34b6254a] %[output:72ecf18e]
    fprintf('MAE: %.3f\n', MAE); %[output:1ab3a4cc] %[output:3bebc95c] %[output:75a8c6b9]
    fprintf('Percentage error: %2f%%\n', percentageError) %[output:40fe7ae0] %[output:49825c81] %[output:0a84ff20]
    fprintf('RMSNE: %2f%%\n', RMSNE) %[output:7e951a06] %[output:1e0f4fdd] %[output:24682399]

    % Plot Parlikar and thermodilution CO
    figure; %[output:8a63bd94] %[output:8ca7ac74] %[output:491a55c1]

    plot(t, CO_parlikar, 'LineWidth', 1.2); %[output:8a63bd94] %[output:8ca7ac74] %[output:491a55c1]
    hold on;

    stem(time_TCO, TCO_valid, 'r', 'LineWidth', 1.2, 'MarkerSize', 3)
    plot(time_TCO, TCO_valid, 'r:o', 'LineWidth', 1.2, 'MarkerSize', 3)
    xlabel('Time (minutes)');
    ylabel('Cardiac Output (L/min)');
    title('Parlikar CO Estimate - ', patients{i});
    legend('ECO', 'TCO');
    grid on;

    saveas(gcf, sprintf('Q5_Parlikar_CO_Estimate_%s.png', patients{i}));

    % Plot estimated tau
    figure; %[output:4f6e784d] %[output:6656d76b] %[output:7a994400]

    plot(t, tau, 'LineWidth', 1.2); %[output:4f6e784d] %[output:6656d76b] %[output:7a994400]
    xlabel('Time (minutes)');
    ylabel('Tau (seconds)');
    title('Parlikar Time Constant (Tau) Estimate', patients{i});
    grid on;

    saveas(gcf, sprintf('Q5_Parlikar_Tau_Estimate_%s.png', patients{i}));

end %[output:group:1517063e]

